// Runtime view of Resources/Story/level_plan.json — the map from story stars to
// concrete level numbers.
//
// The plan is generated by tools/level_plan.py. Nothing here decides anything;
// it only answers "which levels belong to this area" and "what is this level
// for".

using System.Collections.Generic;
using UnityEngine;

namespace JellyGarden.Scripts.Story
{
    public sealed class StoryLevelEntry
    {
        public int LevelNumber;
        public int AreaId;
        public int Arc;
        public int TaskIndex;
        public int StarIndexWithinArea;
        public float Difficulty;
        public string ThemeKey = string.Empty;
        public bool Sabotage;
        public int MinimumMoves;

        /// <summary>True on the single level that introduces Grimm's sabotage.</summary>
        public bool SabotageBeat;
    }

    public static class StoryLevelPlan
    {
        private static bool _loaded;

        private static readonly List<StoryLevelEntry> _levels = new List<StoryLevelEntry>();
        private static readonly Dictionary<int, StoryLevelEntry> _byNumber =
            new Dictionary<int, StoryLevelEntry>();
        private static readonly Dictionary<int, List<int>> _byArea =
            new Dictionary<int, List<int>>();

        public static int LevelCount
        {
            get { Load(); return _levels.Count; }
        }

        public static int FirstSabotageArea { get; private set; }

        public static void Load()
        {
            if (_loaded) return;
            _loaded = true;

            var text = StoryCampaign.LoadText("level_plan");
            if (text == null)
            {
                Debug.LogWarning("[Story] Missing Resources/Story/level_plan.json — " +
                                 "run tools/level_plan.py.");
                return;
            }

            JsonValue root = JsonValue.Parse(text.text);
            FirstSabotageArea = root["firstSabotageArea"].AsInt(int.MaxValue);

            foreach (JsonValue node in root["levels"].Items)
            {
                var entry = new StoryLevelEntry
                {
                    LevelNumber = node["levelNumber"].AsInt(),
                    AreaId = node["areaId"].AsInt(),
                    Arc = node["arc"].AsInt(),
                    TaskIndex = node["taskIndex"].AsInt(),
                    StarIndexWithinArea = node["starIndexWithinArea"].AsInt(),
                    Difficulty = node["difficulty"].AsFloat(),
                    ThemeKey = node["themeKey"].AsString(),
                    Sabotage = node["sabotage"].AsBool(),
                    MinimumMoves = node["minimumMoves"].AsInt(),
                    SabotageBeat = node["sabotageBeat"].AsBool()
                };

                _levels.Add(entry);
                _byNumber[entry.LevelNumber] = entry;

                List<int> areaLevels;
                if (!_byArea.TryGetValue(entry.AreaId, out areaLevels))
                {
                    areaLevels = new List<int>();
                    _byArea[entry.AreaId] = areaLevels;
                }
                areaLevels.Add(entry.LevelNumber);
            }

            Debug.Log(string.Format("[Story] Level plan loaded: {0} levels across {1} areas.",
                _levels.Count, _byArea.Count));
        }

        public static StoryLevelEntry Get(int levelNumber)
        {
            Load();
            StoryLevelEntry entry;
            return _byNumber.TryGetValue(levelNumber, out entry) ? entry : null;
        }

        /// <summary>Every level number belonging to an area, in play order.</summary>
        public static IList<int> LevelsFor(int areaId)
        {
            Load();
            List<int> levels;
            return _byArea.TryGetValue(areaId, out levels) ? levels : new List<int>();
        }

        /// <summary>
        /// The next level the player should play in this area: the first one they
        /// have not beaten. Falls back to replaying the last level once the area's
        /// whole set is beaten, so the Play button is never dead while repairs
        /// remain unpaid.
        /// </summary>
        public static int NextLevelFor(int areaId)
        {
            IList<int> levels = LevelsFor(areaId);
            if (levels.Count == 0) return 0;

            for (int i = 0; i < levels.Count; i++)
                if (!StoryProgress.IsLevelBeaten(levels[i])) return levels[i];

            return levels[levels.Count - 1];
        }

        public static int AreaOf(int levelNumber)
        {
            StoryLevelEntry entry = Get(levelNumber);
            return entry != null ? entry.AreaId : 0;
        }

        public static void Unload()
        {
            _loaded = false;
            _levels.Clear();
            _byNumber.Clear();
            _byArea.Clear();
        }
    }
}
